mapper.select:
select sp.*, p.id 'project.id', p.name 'project.name', p.short_name 'project.short_name', p.serial_number 'project.serial_number', s.id 'supplier.id', s.name 'supplier.name', sp.license_plate, sp.bool_personal_enum, sp.invoice_type_enum, if(count > 0,1,0) boolUseEnwum from mes_enclosure_supplier_price sp left join contract_project p on p.id = sp.project_id left join scm_supplier s on s.id = sp.supplier_id left join ( select supplier_price_id,count(*) count from mes_enclosure_cargo_list where supplier_price_id is not null and bool_delete_enum = 0 group by supplier_price_id ) temp on temp.supplier_price_id = sp.id
sp.bool_delete_enum = 0
AND sp.project_id in
#{projectId}
and s.name like CONCAT('%',#{name},'%') or sp.license_plate like CONCAT('%',#{name},'%')
and p.status = #{status}
and sp.license_plate = #{licensePlate}
order by sp.create_time desc
